// Audience detection hook
export function useAudienceDetection(): 'investor' | 'scientist' | 'partner' | 'candidate' | 'default' {
  const { pathname, searchParams } = useLocation();

  const audienceSignals: Record<string, string> = {
    '/investors': 'investor',
    '/careers': 'candidate',
    '/pipeline': 'investor', // Default pipeline viewers are investors
    '/science': 'scientist',
    '/platform/agents': 'scientist',
    '?ref=ycombinator': 'investor',
    '?ref=linkedin': 'candidate',
  };

  for (const [signal, audience] of Object.entries(audienceSignals)) {
    if (pathname.includes(signal) || searchParams.get('ref')?.includes(signal)) {
      return audience as any;
    }
  }

  return 'default';
}
