// src/components/ContentLayeredPage.tsx
interface ContentLayer {
  id: 'executive' | 'technical' | 'data';
  label: string;
  content: React.ReactNode;
  requiredAuth?: boolean;
}

interface ContentLayeredPageProps {
  title: string;
  layers: ContentLayer[];
  defaultLayer?: 'executive' | 'technical' | 'data';
  downloadableAssets?: DownloadableAsset[];
}

export const ContentLayeredPage: React.FC<ContentLayeredPageProps> = ({
  title,
  layers,
  defaultLayer = 'executive',
  downloadableAssets = [],
}) => {
  const [activeLayer, setActiveLayer] = useState(defaultLayer);
  const { user } = useAuth();

  const layerOrder = ['executive', 'technical', 'data'] as const;

  return (
    <div className="content-layered-page">
      {/* Layer selector tabs */}
      <div className="layer-tabs sticky top-16 z-30 bg-white border-b">
        <div className="max-w-7xl mx-auto px-6 flex gap-6">
          {layers.map((layer) => (
            <button
              key={layer.id}
              onClick={() => setActiveLayer(layer.id)}
              className={`layer-tab py-4 px-2 border-b-2 transition-colors ${
                activeLayer === layer.id
                  ? 'border-brown-600 text-brown-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
              disabled={layer.requiredAuth && !user}
            >
              {layer.id === 'executive' && '📋'} 
              {layer.id === 'technical' && '🔬'}
              {layer.id === 'data' && '📊'}
              {' '}{layer.label}
              {layer.requiredAuth && !user && ' 🔒'}
            </button>
          ))}
        </div>
      </div>

      {/* Layer content */}
      <div className="layer-content max-w-7xl mx-auto px-6 py-12">
        {layers
          .filter((l) => l.id === activeLayer)
          .map((layer) => (
            <div key={layer.id}>
              {layer.content}

              {/* Progressive disclosure: link to deeper layer */}
              {layer.id !== 'data' && (
                <div className="mt-8 pt-8 border-t">
                  <p className="text-gray-500 text-sm">
                    Want more detail?{' '}
                    <button
                      onClick={() => {
                        const nextIndex = layerOrder.indexOf(layer.id) + 1;
                        setActiveLayer(layerOrder[nextIndex]);
                      }}
                      className="text-brown-600 underline"
                    >
                      Dive into {layers.find(l => l.id === layerOrder[layerOrder.indexOf(layer.id) + 1])?.label}
                    </button>
                  </p>
                </div>
              )}
            </div>
          ))}
      </div>

      {/* Downloadable assets sidebar */}
      {downloadableAssets.length > 0 && (
        <aside className="download-sidebar fixed right-0 top-1/2 -translate-y-1/2">
          <DownloadPanel assets={downloadableAssets} />
        </aside>
      )}
    </div>
  );
};
