// src/hooks/useARPData.ts
import { useQuery } from '@tanstack/react-query';
import { arpApiClient } from '@/lib/api/arp-client';

interface DoseResponsePoint {
  concentration: number;
  viability: number;
  standardError: number;
}

interface ARPDataResponse {
  dgat1Data: {
    doseResponse: DoseResponsePoint[];
    selectivity: { dgat1: number; dgat2: number };
    scaffolds: ScaffoldData[];
  };
  yars2Data: {
    doseResponse: DoseResponsePoint[];
    bindingAffinity: { kd: number; kon: number; koff: number };
    scaffolds: ScaffoldData[];
  };
  agentOutputs: {
    literature: { papersAnalyzed: number; keyFindings: string[] };
    multiOmics: { vulnerabilities: VulnerabilityData[] };
    virtualScreen: { compoundsScreened: number; hitRate: number };
    design: { scaffoldsGenerated: number; noveltyScore: number };
    admet: { candidatesPrioritized: number; passRate: number };
    wetLab: { leadsValidated: number; timeline: string };
  };
}

export function useARPData() {
  return useQuery<ARPDataResponse>({
    queryKey: ['arp-v3-data', 'dgat1', 'yars2'],
    queryFn: () => arpApiClient.getValidationData(),
    staleTime: 1000 * 60 * 60, // 1 hour
    refetchOnWindowFocus: false,
  });
}

// For gated downloads
export function useGatedDownload(assetId: string) {
  const { user } = useAuth();
  const [isRequesting, setIsRequesting] = useState(false);

  const requestAccess = async (email: string, reason: string) => {
    setIsRequesting(true);
    try {
      await arpApiClient.requestAssetAccess(assetId, { email, reason });
      return { success: true };
    } catch {
      return { success: false };
    } finally {
      setIsRequesting(false);
    }
  };

  return {
    canDownload: user?.verifiedScientist || user?.investor,
    requestAccess,
    isRequesting,
  };
}
```

